// src/gateway.js
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const helmet = require('helmet');
const winston = require('winston');
const fs = require('fs');
const path = require('path');

// Load configuration
const config = require('./config');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors());

// Rate limiting
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: config.RATE_LIMIT || 100,
});
app.use(limiter);

// Logging setup
const logger = winston.createLogger({
  level: config.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - ${req.ip}`);
  next();
});

// Body parsing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Routes
app.use('/auth', require('./auth'));

// API proxy
app.use('/api', (req, res) => {
  // Authentication check
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, config.JWT_SECRET);
    req.user = decoded;
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }

  // Proxy to internal service
  // In a real implementation, this would forward to the appropriate service
  // For this example, we'll just return a success response
  res.json({
    message: 'Request proxied successfully',
    service: req.path.split('/')[2],
    user: req.user
  });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', version: '1.4.2' });
});

// Start server
const PORT = config.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Relay Gateway running on port ${PORT}`);
  logger.info(`Server started on port ${PORT}`);
});

module.exports = app;

