// src/auth.js
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const validator = require('validator');
const fs = require('fs');
const path = require('path');

const router = express.Router();

// In-memory user store (for demo purposes only)
// In production, this would connect to a database
const users = [
  {
    id: 1,
    username: 'admin',
    email: 'admin@morrowline.com',
    password: '$2b$10$EaSWez59Zp9yjZ1qJZ7e.eL5p9Z1qJZ7e.eL5p9Z1qJZ7e.eL5p9Z1qJ', // bcrypt hash of 'admin123'
    role: 'admin'
  }
];

// Login endpoint
router.post('/login', (req, res) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Find user
  const user = users.find(u => u.username === username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Check password
  bcrypt.compare(password, user.password, (err, result) => {
    if (err || !result) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT token
    const token = jwt.sign(
      { id: user.id, username: user.username, role: user.role },
      process.env.JWT_SECRET || 'development-secret-key',
      { expiresIn: '1h' }
    );

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        role: user.role
      }
    });
  });
});

// Token validation endpoint
router.post('/validate', (req, res) => {
  const token = req.body.token;

  if (!token) {
    return res.status(400).json({ error: 'Token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'development-secret-key');
    res.json({ valid: true, user: decoded });
  } catch (err) {
    res.json({ valid: false, error: 'Invalid or expired token' });
  }
});

module.exports = router;

