// src/utils.js
// Utility functions for the Relay Gateway

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Generate a random token
exports.generateToken = (length = 32) => {
  return crypto.randomBytes(Math.ceil(length / 2)).toString('hex').slice(0, length);
};

// Validate email address
exports.validateEmail = (email) => {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
};

// Sanitize user input
exports.sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input.trim().replace(/<[^>]*>/g, '');
};

// Read configuration file
exports.readConfig = (configPath) => {
  try {
    const configData = fs.readFileSync(configPath, 'utf8');
    return JSON.parse(configData);
  } catch (err) {
    console.error(`Error reading config file ${configPath}:`, err.message);
    return null;
  }
};

// Write configuration file
exports.writeConfig = (configPath, config) => {
  try {
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
    return true;
  } catch (err) {
    console.error(`Error writing config file ${configPath}:`, err.message);
    return false;
  }
};

// Log security event
exports.logSecurityEvent = (event, metadata = {}) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event,
    ...metadata
  };

  // In a real implementation, this would write to a secure audit log
  // For this example, we'll just log to console
  console.log('SECURITY EVENT:', JSON.stringify(logEntry));
};

